// Builds components/logos/logos.ts from simple-icons (CC0 data): a curated list, not the whole set.
// Run with `bun run logos`. simple-icons stays a devDependency; the site only reads the generated file.
import { readFileSync, writeFileSync } from "node:fs";
import * as si from "simple-icons";

/** Category → simple-icons slugs, in display order. Slugs simple-icons no longer ships are skipped. No crypto or web3. */
const CURATED: Record<string, string[]> = {
  "Dev tools": [
    "github", "gitlab", "bitbucket", "git", "githubactions", "linear", "discord", "vercel", "netlify", "cloudflare", "docker",
    "kubernetes", "npm", "pnpm", "yarn", "vite", "webpack", "turborepo", "postman", "sentry", "grafana",
    "terraform", "nginx", "homebrew", "neovim", "vim", "jetbrains", "zedindustries", "warp", "iterm2", "eslint",
    "prettier", "biome", "storybook", "vitest", "jest", "cypress",
  ],
  "Languages & frameworks": [
    "typescript", "javascript", "python", "rust", "go", "nodedotjs", "bun", "deno", "react", "nextdotjs",
    "vuedotjs", "nuxt", "svelte", "astro", "remix", "angular", "solid", "tailwindcss", "html5", "css",
    "sass", "php", "laravel", "django", "fastapi", "rubyonrails", "ruby", "swift", "kotlin", "flutter",
    "dart", "elixir", "zig", "cplusplus", "graphql", "prisma", "drizzle", "threedotjs", "shadcnui", "radixui",
    "expo", "electron", "tauri",
  ],
  "Cloud & data": [
    "googlecloud", "digitalocean", "hetzner", "firebase", "supabase", "railway", "render", "flydotio", "cloudflareworkers", "postgresql",
    "mysql", "sqlite", "redis", "mongodb", "planetscale", "neon", "upstash", "clickhouse", "elastic", "snowflake",
    "databricks", "apachekafka",
  ],
  AI: [
    "anthropic", "claude", "googlegemini", "githubcopilot", "cursor", "huggingface", "ollama", "mistralai", "perplexity", "deepseek",
    "langchain", "replicate", "nvidia", "tensorflow", "pytorch", "jupyter", "kaggle",
  ],
  "Payments & commerce": [
    "stripe", "paypal", "visa", "mastercard", "americanexpress", "applepay", "googlepay", "klarna", "shopify", "woocommerce",
    "square", "wise", "revolut", "lemonsqueezy", "gumroad", "paddle",
  ],
  Social: [
    "x", "youtube", "instagram", "facebook", "threads", "tiktok", "reddit", "telegram", "whatsapp", "signal",
    "messenger", "snapchat", "pinterest", "twitch", "bluesky", "mastodon", "medium", "substack", "dribbble", "behance",
    "producthunt", "ycombinator", "stackoverflow", "devdotto",
  ],
  "Design & productivity": [
    "figma", "framer", "webflow", "sketch", "blender", "miro", "notion", "obsidian", "raycast", "zoom",
    "dropbox", "asana", "trello", "jira", "confluence", "clickup", "airtable", "loom", "calendly", "todoist",
    "1password", "bitwarden", "zapier", "n8n", "make", "posthog", "googleanalytics", "hubspot", "intercom", "resend",
  ],
  Platforms: [
    "apple", "google", "android", "ios", "macos", "linux", "ubuntu", "debian", "archlinux", "googlechrome",
    "firefox", "safari", "brave", "arc", "opera", "gmail", "googledrive", "googlemaps", "googlecalendar", "googledocs",
    "googlesheets", "googlemeet", "samsung", "spotify", "netflix", "steam",
  ],
};

type SimpleIcon = { slug: string; title: string; hex: string; path: string };
const bySlug = new Map((Object.values(si) as unknown as SimpleIcon[]).filter((i) => i && typeof i === "object" && "slug" in i).map((i) => [i.slug, i]));

const seen = new Set<string>();
const missing: string[] = [];
const rows: string[] = [];
const counts: [string, number][] = [];

for (const [category, slugs] of Object.entries(CURATED)) {
  let n = 0;
  for (const slug of slugs) {
    const icon = bySlug.get(slug);
    if (!icon) {
      missing.push(slug);
      continue;
    }
    if (seen.has(slug)) throw new Error(`duplicate slug: ${slug}`);
    seen.add(slug);
    rows.push(`  { slug: ${JSON.stringify(slug)}, title: ${JSON.stringify(icon.title)}, hex: "${icon.hex}", category: ${JSON.stringify(category)}, path: "${icon.path}" },`);
    n++;
  }
  counts.push([category, n]);
}

const version = (JSON.parse(readFileSync(new URL("../node_modules/simple-icons/package.json", import.meta.url), "utf8")) as { version: string }).version;
const out = `// Generated by scripts/gen-logos.ts from simple-icons ${version} (CC0). Do not edit by hand: run \`bun run logos\`.
// Logos are trademarks of their owners. All paths are on a 24×24 viewBox.

export interface Logo {
  slug: string;
  title: string;
  /** Brand colour, six hex digits without "#". */
  hex: string;
  category: LogoCategory;
  path: string;
}

export const LOGO_CATEGORIES = ${JSON.stringify(Object.keys(CURATED))} as const;
export type LogoCategory = (typeof LOGO_CATEGORIES)[number];

export const LOGOS: Logo[] = [
${rows.join("\n")}
];
`;

writeFileSync(new URL("../components/logos/logos.ts", import.meta.url), out);
console.log(`logos: ${rows.length} written (${counts.map(([c, n]) => `${c} ${n}`).join(", ")})`);
if (missing.length) console.log(`skipped (not in simple-icons): ${missing.join(" ")}`);
